   "code": "// Client side: idempotent send, gap detection, resume after reconnect\nconst pending = new Map();     // clientId -> message\nlet lastSeq = Number(localStorage.getItem('lastSeq:' + convId) || 0);\n\nfunction send(text) {\n  const msg = { clientId: crypto.randomUUID(), convId, text };\n  pending.set(msg.clientId, msg);\n  ws.send(JSON.stringify({ type: 'send', ...msg }));     // resend the same clientId on reconnect\n}\nws.onmessage = e => {\n  const m = JSON.parse(e.data);\n  if (m.type === 'ack') { pending.delete(m.clientId); markSent(m.clientId, m.seq); }\n  if (m.type === 'msg') {\n    if (m.seq > lastSeq + 1) fetchRange(convId, lastSeq + 1, m.seq - 1);   // fill the gap\n    if (m.seq > lastSeq) { lastSeq = m.seq; localStorage.setItem('lastSeq:' + convId, lastSeq); render(m); }\n  }\n};\nws.onopen = () => {\n  ws.send(JSON.stringify({ type: 'resume', convId, afterSeq: lastSeq }));\n  for (const msg of pending.values()) ws.send(JSON.stringify({ type: 'send', ...msg }));\n};",
