   "code": "// Throttle, bundle and dedupe before sending\nasync function enqueueNotification(n) {\n  // n = { userId, category, templateId, data, priority, key }\n  if (!(await redis.set(`notif:dedupe:${n.key}`, '1', { NX: true, EX: 86400 }))) return 'duplicate';\n  const prefs = await prefsFor(n.userId);\n  const channels = prefs.channelsFor(n.category);           // e.g. ['push'] or [] if opted out\n  if (!channels.length) return 'opted-out';\n  if (n.priority === 'low') {\n    const count = await redis.incr(`notif:bundle:${n.userId}:${n.category}`);\n    await redis.expire(`notif:bundle:${n.userId}:${n.category}`, 3600);\n    if (count > 1) return 'bundled';                         // a digest job sends \"N new likes\" later\n  }\n  const sendAt = n.priority === 'high' ? Date.now() : nextWakingTime(prefs.timeZone);\n  await queues[n.priority].send({ ...n, channels, sendAt });\n  return 'queued';\n}",
