   "code": "// Geohash encode + nearby search over 9 cells\nconst B32 = '0123456789bcdefghjkmnpqrstuvwxyz';\nfunction geohash(lat, lon, len = 6) {\n  let latR = [-90, 90], lonR = [-180, 180], bits = 0, n = 0, even = true, out = '';\n  while (out.length < len) {\n    const r = even ? lonR : latR, v = even ? lon : lat, mid = (r[0] + r[1]) / 2;\n    if (v >= mid) { n = n * 2 + 1; r[0] = mid; } else { n = n * 2; r[1] = mid; }\n    even = !even;\n    if (++bits === 5) { out += B32[n]; bits = 0; n = 0; }\n  }\n  return out;\n}\nconst km = (a, b) => { const R = 6371, d = x => x * Math.PI / 180;\n  const h = Math.sin(d(b.lat - a.lat) / 2) ** 2 + Math.cos(d(a.lat)) * Math.cos(d(b.lat)) * Math.sin(d(b.lon - a.lon) / 2) ** 2;\n  return 2 * R * Math.asin(Math.sqrt(h)); };\n\nconst me = { lat: -23.5617, lon: -46.6560 };                      // Av. Paulista, São Paulo\nconsole.log('my cell', geohash(me.lat, me.lon));\nconst places = [{ n: 'cafe', lat: -23.5630, lon: -46.6544 }, { n: 'museum', lat: -23.5614, lon: -46.6559 }, { n: 'far', lat: -23.6, lon: -46.7 }];\nconst neighbours = new Set();                                       // cells around me (approximate with small offsets)\nfor (const dLat of [-0.011, 0, 0.011]) for (const dLon of [-0.011, 0, 0.011]) neighbours.add(geohash(me.lat + dLat, me.lon + dLon));\nconst near = places.filter(p => neighbours.has(geohash(p.lat, p.lon))).map(p => ({ ...p, km: +km(me, p).toFixed(2) })).sort((a, b) => a.km - b.km);\nconsole.log(near.map(p => p.n + ' ' + p.km + ' km'));",
