   "code": "// A tiny adaptive bitrate chooser: pick the highest rendition the network and buffer allow\nconst ladder = [{ h: 240, kbps: 400 }, { h: 480, kbps: 1200 }, { h: 720, kbps: 3000 }, { h: 1080, kbps: 5500 }, { h: 2160, kbps: 15000 }];\nfunction chooseRendition(measuredKbps, bufferSec) {\n  const safety = bufferSec < 10 ? 0.5 : bufferSec < 30 ? 0.75 : 0.9;     // be careful when the buffer is low\n  const budget = measuredKbps * safety;\n  return [...ladder].reverse().find(r => r.kbps <= budget) || ladder[0];\n}\nconsole.log(chooseRendition(8000, 40).h);  // 1080\nconsole.log(chooseRendition(8000, 5).h);   // 720  (low buffer: play it safe)\nconsole.log(chooseRendition(900, 20).h);   // 240\n\n// Monthly egress estimate\nconst egressTB = (viewers, hoursEach, avgMbps) => viewers * hoursEach * 3600 * avgMbps / 8 / 1e6;\nconsole.log(egressTB(1e6, 20, 4).toLocaleString(), 'TB per month'); // 36,000 TB",
