   "code": "// Build a prefix -> top-K map from query counts, then serve lookups\nfunction buildPrefixIndex(counts, k = 5, maxLen = 15) {\n  const idx = new Map();\n  for (const [q, n] of Object.entries(counts)) {\n    for (let i = 1; i <= Math.min(q.length, maxLen); i++) {\n      const p = q.slice(0, i), list = idx.get(p) || [];\n      list.push([q, n]); list.sort((a, b) => b[1] - a[1]); if (list.length > k) list.pop();\n      idx.set(p, list);\n    }\n  }\n  return idx;\n}\nconst counts = { 'system design': 900, 'system design interview': 700, 'sysadmin': 120, 'syntax error': 300, 'synonym': 200 };\nconst idx = buildPrefixIndex(counts);\nconsole.log((idx.get('sy') || []).map(x => x[0]));     // most popular first\nconsole.log((idx.get('syn') || []).map(x => x[0]));\n\n// Client: debounce and ignore out-of-date responses\nfunction typeahead(input, fetchSuggestions, render) {\n  let timer, latest = '';\n  input.addEventListener('input', () => {\n    clearTimeout(timer);\n    timer = setTimeout(async () => {\n      const q = (latest = input.value.trim());\n      if (!q) return render([]);\n      const res = await fetchSuggestions(q);\n      if (q === latest) render(res);                       // drop responses for older prefixes\n    }, 150);\n  });\n}",
